const p=s=>`<p>${s}</p>`;
const pair=(body,figure)=>`<div class="dy-pair"><div class="dy-stack">${body}</div>${figure}</div>`;
const table=(heads,rows)=>`<div class="dy-table-wrap" data-d20-scroll tabindex="0" role="region" aria-label="Mathematical table; scroll horizontally if needed"><table class="dy-table"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>i?`<td>${v}</td>`:`<th scope="row">${v}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const slide=(key,title,html,referencePages,options={})=>({id:`l20-${key}`,key,title,html,referencePages,className:'dy-slide',...options});
const cp=(promptHtml,choices,correctIndex,explanationHtml)=>({promptHtml,choices:choices.map(html=>({html})),correctIndex,explanationHtml,autoOpen:true});
const link=(key,label)=>`<a data-d20-link="${key}" href="#slide=1">${label}</a>`;
function priceWidget(){return `<div data-price-widget class="d20-price-widget"><figure class="dy-figure" data-price-graphic>${priceGraphic(.6)}</figure><div class="d20-price-details"><div class="dy-controls" data-screen-only><label for="l20-price-epsilon">Change in requirement 2 <input id="l20-price-epsilon" data-price-input type="range" min="-3" max="2" step="0.1" value="0.6"/></label><button type="button" data-price-reset>Reset change</button></div><p data-price-status class="dy-price-status" role="status">Change 0.6: quantities (1.2, 0, 0.667); cost 19.6. The current basis remains feasible and optimal.</p></div></div>`;}
function mountPrice({slideElement}){
 const root=slideElement.querySelector('[data-price-widget]'); if(!root)return;
 const input=root.querySelector('[data-price-input]'),reset=root.querySelector('[data-price-reset]');
 const fmt=n=>Number(n.toFixed(3)).toString();
 const update=()=>{const s=priceState(Number(input.value));root.dataset.state=JSON.stringify(s);root.querySelector('[data-price-graphic]').innerHTML=priceGraphic(s.epsilon);
 const status=`Change ${fmt(s.epsilon)}: quantities (${s.x.map(fmt).join(', ')}); ${s.valid?'cost':'predicted cost'} ${fmt(s.value)}. ${s.valid?'The current basis remains feasible and optimal.':'A quantity is negative. Reoptimize; this is no longer an attainable cost from this basis.'}`;
 root.querySelector('[data-price-status]').textContent=status;input.setAttribute('aria-valuetext',status);};
 const restore=()=>{input.value='.6';update();};input.addEventListener('input',update);reset.addEventListener('click',restore);update();
 return()=>{input.removeEventListener('input',update);reset.removeEventListener('click',restore);};
}
// The dictionary and tableau use the same minimization convention throughout.
const lp47=()=>math(raw`\begin{aligned}\min\quad&f=2x_1+6x_2+10x_3\\\text{s.t.}\quad&-2x_1+4x_2+x_3+x_4=2,\\&4x_1-2x_2-3x_3+x_5=-1,\quad x\ge0.\end{aligned}`);
const dict47=(final=false)=>math(final?raw`\begin{aligned}x_2&=\tfrac12+2x_1-\tfrac32x_3+\tfrac12x_5,\\x_4&=-6x_1+5x_3-2x_5,\\f&=3+14x_1+x_3+3x_5.\end{aligned}`:raw`\begin{aligned}x_4&=2+2x_1-4x_2-x_3,\\x_5&=-1-4x_1+2x_2+3x_3,\\f&=2x_1+6x_2+10x_3.\end{aligned}`);
const lp48=()=>math(raw`\min\ f=x_1+x_2\quad\text{s.t.}\quad x_1+2x_2\ge2,\quad x_1\ge1,\quad x_1,x_2\ge0.`);
const dual48=()=>math(raw`\max\ 2p_1+p_2\quad\text{s.t.}\quad p_1+p_2\le1,\quad2p_1\le1,\quad p_1,p_2\ge0.`);
const dict48=(stage=0)=>math([
raw`\begin{aligned}x_3&=-2+x_1+2x_2,\\x_4&=-1+x_1,\\f&=x_1+x_2.\end{aligned}`,
raw`\begin{aligned}x_2&=1-\tfrac12x_1+\tfrac12x_3,\\x_4&=-1+x_1,\\f&=1+\tfrac12x_1+\tfrac12x_3.\end{aligned}`,
raw`\begin{aligned}x_1&=1+x_4,\\x_2&=\tfrac12+\tfrac12x_3-\tfrac12x_4,\\f&=\tfrac32+\tfrac12x_3+\tfrac12x_4.\end{aligned}`][stage]);
const lp49=()=>math(raw`\min\ f=3x_1+x_2\quad\text{s.t.}\quad x_1+x_2\ge2,\quad2x_1-x_2\ge0,\quad x_1,x_2\ge0.`);
const dual49=()=>math(raw`\max\ 2p_1\quad\text{s.t.}\quad p_1+2p_2\le3,\quad p_1-p_2\le1,\quad p_1,p_2\ge0.`);
const tableau=(heads,rows)=>table(['Row','Column 0',...heads.map(j=>raw`\(x_${j}\)`)],rows.map(row=>row.map(v=>raw`\(${v}\)`)));
const tab47=(final=false)=>tableau([1,2,3,4,5],final?[
 ['R_0','-3','14','0','1','0','3'],['x_4','0','6','0','-5','1','2'],['x_2','1/2','-2','1','3/2','0','-1/2']]:[
 ['R_0','0','2','6','10','0','0'],['x_4','2','-2','4','1','1','0'],['x_5','-1','4','-2','-3','0','1']]);
const tab48=(stage)=>tableau([1,2,3,4],[
 [['R_0','0','1','1','0','0'],['x_3','-2','-1','-2','1','0'],['x_4','-1','-1','0','0','1']],
 [['R_0','-1','1/2','0','1/2','0'],['x_2','1','1/2','1','-1/2','0'],['x_4','-1','-1','0','0','1']],
 [['R_0','-3/2','0','0','1/2','1/2'],['x_1','1','1','0','0','-1'],['x_2','1/2','0','1','-1/2','1/2']]][stage]);
const signReminder=()=>p(raw`Column 0 is the RHS in constraint rows and \(-f_0\) in \(R_0\), where \(f=f_0+\sum_{j\in\mathcal N}\bar c_jx_j\). Columns always follow natural variable order.`);
function clipPolygon(poly,a,b,c){const out=[];for(let i=0;i<poly.length;i++){const u=poly[i],v=poly[(i+1)%poly.length],fu=a*u[0]+b*u[1]-c,fv=a*v[0]+b*v[1]-c;if(fu<=1e-9)out.push(u);if((fu<=0)!==(fv<=0)){const t=fu/(fu-fv);out.push([u[0]+t*(v[0]-u[0]),u[1]+t*(v[1]-u[1])]);}}return out;}
export function dualGeometry(example=48,stage=2){
 const is48=example===48;
 const panel=(dual=false)=>{
  const ox=dual?535:35,oy=is48?300:260,sx=is48?(dual?300:150):(dual?120:125),sy=is48?(dual?210:130):(dual?75:75);
  const X=x=>ox+35+x*sx,Y=y=>oy-y*sy;
  let poly=is48?(dual?[[0,0],[1.15,0],[1.15,1.15],[0,1.15]]:[[0,0],[2.65,0],[2.65,1.8],[0,1.8]]):(dual?[[0,0],[3.35,0],[3.35,2.1],[0,2.1]]:[[0,0],[3.15,0],[3.15,2.6],[0,2.6]]);
  const constraints=is48?(dual?[[1,1,1],[2,0,1]]:[[-1,-2,-2],[-1,0,-1]]):(dual?[[1,2,3],[1,-1,1]]:[[-1,-1,-2],[-2,1,0]]);
  constraints.forEach(v=>poly=clipPolygon(poly,...v));
  const line=(a,b,color='#326b8c',width=3,dash='')=>`<line x1="${X(a[0])}" y1="${Y(a[1])}" x2="${X(b[0])}" y2="${Y(b[1])}" stroke="${color}" stroke-width="${width}" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
  const pts=is48?(dual?[[0,0,'A'],[.5,0,'B'],[.5,.5,'C'],[0,1,'D'],[1,0,'E']]:[[0,0,'A'],[0,1,'B'],[1,.5,'C'],[1,0,'D'],[2,0,'E']]):(dual?[[0,0,'A'],[0,1.5,'A′'],[0,-1,'A″'],[1,0,'B'],[5/3,2/3,'C'],[3,0,'D']]:[[0,0,'A'],[0,2,'B'],[2/3,4/3,'C'],[2,0,'D']]);
  let out=`<text x="${ox+220}" y="28" text-anchor="middle" class="d20-plot-title">${dual?'Dual variables':'Primal variables'}</text><polygon points="${poly.map(q=>`${X(q[0])},${Y(q[1])}`).join(' ')}" fill="#d9eaf2"/>`;
  out+=line([-.1,0],[is48?(dual?1.25:2.75):3.4,0],'#697d88',2)+line([0,is48?-.05:dual?-1.12:-.05],[0,is48?(dual?1.15:1.85):2.7],'#697d88',2);
  const segments=is48?(dual?[[[0,1],[1,0]],[[.5,0],[.5,1.1]]]:[[[0,1],[2,0]],[[1,0],[1,1.8]]]):(dual?[[[0,1.5],[3,0]],[[0,-1],[3.1,2.1]]]:[[[0,2],[2,0]],[[0,0],[1.3,2.6]]]);
  segments.forEach((s,i)=>{out+=line(...s,i?'#177441':'#326b8c');});
  if(is48){const path=pts.slice(0,Math.min(stage+1,3));for(let i=1;i<path.length;i++){out+=line(path[i-1],path[i],'#c85313',6);const u=path[i-1],v=path[i],dx=X(v[0])-X(u[0]),dy=Y(v[1])-Y(u[1]),len=Math.hypot(dx,dy),tx=X(v[0])-dx/len*9,ty=Y(v[1])-dy/len*9;out+=`<polygon points="${tx},${ty} ${tx-dx/len*14-dy/len*7},${ty-dy/len*14+dx/len*7} ${tx-dx/len*14+dy/len*7},${ty-dy/len*14-dx/len*7}" fill="#c85313"/>`;}}
  pts.forEach(([x,y,label],i)=>{const chosen=is48&&i===stage;out+=`<circle data-basis-label="${label}" data-space="${dual?'dual':'primal'}" data-world="${x},${y}" cx="${X(x)}" cy="${Y(y)}" r="${chosen?8:5}" fill="${chosen?'#861f41':'#326b8c'}" stroke="white" stroke-width="2"/><text x="${X(x)+(x===0?-12:12)}" y="${Y(y)+(!is48&&dual&&label==='D'?-12:y===0?26:-12)}" text-anchor="${x===0?'end':'start'}">${label}</text>`;});
  const arr=is48?(dual?[[.72,.78],[1.02,.93]]:[[1.8,1.05],[2.15,1.4]]):(dual?[[2.1,-.62],[2.65,-.62]]:[[1.65,1.8],[2.25,2.0]]);
  out+=line(...arr,'#861f41',3);const tip=arr[1],tail=arr[0],dx=X(tip[0])-X(tail[0]),dy=Y(tip[1])-Y(tail[1]),len=Math.hypot(dx,dy);out+=`<polygon points="${X(tip[0])},${Y(tip[1])} ${X(tip[0])-dx/len*12-dy/len*6},${Y(tip[1])-dy/len*12+dx/len*6} ${X(tip[0])-dx/len*12+dy/len*6},${Y(tip[1])-dy/len*12-dx/len*6}" fill="#861f41"/><text x="${X(tail[0])}" y="${Y(tail[1])-12}">${dual?'b':'c'}</text>`;
  out+=`<text x="${ox+420}" y="${oy+23}">${dual?'p₁':'x₁'}</text><text x="${ox+15}" y="57">${dual?'p₂':'x₂'}</text>`;
  return out;
 };
 return `<figure class="dy-figure d20-dual-geometry" data-d20-scroll tabindex="0" aria-label="Paired primal and dual plots; scroll horizontally on narrow screens"><svg viewBox="0 0 1040 350" role="img" aria-label="Example ${example===48?'4.8':'4.9'}: corresponding primal and dual basic solutions. Blue shading is feasible. ${is48?'The dual-simplex path A to B to C stays dual feasible and becomes primal feasible at C.':'Three bases at primal point A correspond to distinct dual points A, A prime, and A double prime; A double prime is infeasible.'}">${panel(false)}${panel(true)}</svg><figcaption>${is48?'Blue: feasible region (clipped). Orange: pivot path. Arrows: increasing objective.':'Blue: feasible region (clipped). Arrows: increasing objective.'}</figcaption></figure>`;
}
function mountScrollRegions({slideElement}){
 const cleanups=[...slideElement.querySelectorAll('[data-d20-scroll]')].map(region=>{const handler=event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key)||region.scrollWidth<=region.clientWidth)return;event.preventDefault();event.stopPropagation();region.scrollBy({left:event.key==='ArrowRight'?100:-100,behavior:'auto'});};region.addEventListener('keydown',handler);return()=>region.removeEventListener('keydown',handler);});
 return()=>cleanups.forEach(cleanup=>cleanup());
}
